/**
 * Bun utility script that validates JSON input from stdin.
 *
 * Usage: echo '{"key": "value"}' | bun run src/validate-json.ts
 * Exit code 0 for valid JSON, 1 for invalid.
 */

/**
 * Validate a string as JSON.
 * Returns an object with `valid` boolean and optional `error` message.
 */
export function validateJson(input: string): { valid: boolean; error?: string } {
  const trimmed = input.trim();

  if (trimmed.length === 0) {
    return { valid: false, error: "Empty input: no JSON provided" };
  }

  try {
    JSON.parse(trimmed);
    return { valid: true };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { valid: false, error: `Invalid JSON: ${message}` };
  }
}

/**
 * Read all stdin and validate as JSON.
 */
async function main(): Promise<void> {
  const input = await Bun.stdin.text();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(result.error);
    process.exit(1);
  }
}

// Run only when executed directly (not imported)
const isMainModule = import.meta.main;
if (isMainModule) {
  main();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns valid for a correct JSON object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for a JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for a JSON string", () => {
    const result = validateJson('"hello"');
    expect(result.valid).toBe(true);
  });

  test("returns valid for a JSON number", () => {
    const result = validateJson("42");
    expect(result.valid).toBe(true);
  });

  test("returns valid for JSON with whitespace padding", () => {
    const result = validateJson('  {"key": "value"}  \n');
    expect(result.valid).toBe(true);
  });

  test("returns invalid for malformed JSON", () => {
    const result = validateJson("{invalid json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.error).toContain("Invalid JSON");
  });

  test("returns invalid for empty string", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input: no JSON provided");
  });

  test("returns invalid for whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input: no JSON provided");
  });

  test("returns invalid for trailing comma", () => {
    const result = validateJson('{"key": "value",}');
    expect(result.valid).toBe(false);
    expect(result.error).toContain("Invalid JSON");
  });
});

