/**
 * Greeting utility functions for creating personalized greetings.
 */

/**
 * Create a personalized greeting.
 * @param name - The name to greet
 * @param prefix - Optional greeting prefix (defaults to "Hello")
 * @returns The formatted greeting string
 */
export function createGreeting(name: string, prefix: string = "Hello"): string {
  return `${prefix}, ${name}!`;
}

/**
 * Get a time-appropriate greeting based on the hour of day.
 * @param hour - The hour in 24-hour format (0-23)
 * @returns A time-appropriate greeting string
 */
export function getTimeGreeting(hour: number): string {
  if (hour >= 5 && hour <= 11) {
    return "Good morning";
  } else if (hour >= 12 && hour <= 17) {
    return "Good afternoon";
  } else if (hour >= 18 && hour <= 21) {
    return "Good evening";
  } else {
    return "Good night";
  }
}

import { describe, expect, test } from "bun:test";
import { createGreeting, getTimeGreeting } from "./greeting";

describe("greeting", () => {
  describe("createGreeting", () => {
    test("returns greeting with default prefix", () => {
      expect(createGreeting("Alice")).toBe("Hello, Alice!");
    });

    test("returns greeting with custom prefix", () => {
      expect(createGreeting("Bob", "Hi")).toBe("Hi, Bob!");
    });

    test("handles empty name", () => {
      expect(createGreeting("")).toBe("Hello, !");
    });
  });

