    test("returns Good morning for morning hours (5-11)", () => {
      expect(getTimeGreeting(5)).toBe("Good morning");
      expect(getTimeGreeting(9)).toBe("Good morning");
      expect(getTimeGreeting(11)).toBe("Good morning");
    });

    test("returns Good afternoon for afternoon hours (12-17)", () => {
      expect(getTimeGreeting(12)).toBe("Good afternoon");
      expect(getTimeGreeting(14)).toBe("Good afternoon");
      expect(getTimeGreeting(17)).toBe("Good afternoon");
    });

    test("returns Good evening for evening hours (18-21)", () => {
      expect(getTimeGreeting(18)).toBe("Good evening");
      expect(getTimeGreeting(19)).toBe("Good evening");
      expect(getTimeGreeting(21)).toBe("Good evening");
