        "file_path": "/private/tmp/rp1-evals/e44d2324/workspace/src/json-validator.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson, validateJsonFast } from \"./json-validator\";\n\ndescribe(\"json-validator\", () => {\n  describe(\"validateJson\", () => {\n    describe(\"valid JSON values\", () => {\n      test(\"validates empty object\", () => {\n        const result = validateJson(\"{}\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates empty array\", () => {\n        const result = validateJson(\"[]\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates string\", () => {\n        const result = validateJson('\"hello\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates integer\", () => {\n        const result = validateJson(\"42\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates negative number\", () => {\n        const result = validateJson(\"-17\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates decimal number\", () => {\n        const result = validateJson(\"3.14\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates scientific notation\", () => {\n        const result = validateJson(\"1.5e10\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates negative exponent\", () => {\n        const result = validateJson(\"2.5E-3\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates positive exponent\", () => {\n        const result = validateJson(\"1e+5\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates true\", () => {\n        const result = validateJson(\"true\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates false\", () => {\n        const result = validateJson(\"false\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates null\", () => {\n        const result = validateJson(\"null\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates zero\", () => {\n        const result = validateJson(\"0\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates negative zero\", () => {\n        const result = validateJson(\"-0\");\n        expect(result.valid).toBe(true);\n      });\n    });\n\n    describe(\"valid complex structures\", () => {\n      test(\"validates object with string values\", () => {\n        const result = validateJson('{\"name\": \"Alice\", \"city\": \"Wonderland\"}');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates nested objects\", () => {\n        const result = validateJson('{\"a\": {\"b\": {\"c\": 1}}}');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates array of numbers\", () => {\n        const result = validateJson(\"[1, 2, 3, 4, 5]\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates array of mixed types\", () => {\n        const result = validateJson('[1, \"two\", true, null, {\"five\": 5}]');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates nested arrays\", () => {\n        const result = validateJson(\"[[1, 2], [3, [4, 5]]]\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates complex nested structure\", () => {\n        const json = '{\"users\": [{\"name\": \"Bob\", \"age\": 30, \"active\": true, \"meta\": null}]}';\n        const result = validateJson(json);\n        expect(result.valid).toBe(true);\n      });\n    });\n\n    describe(\"valid string escapes\", () => {\n      test(\"validates escaped quotes\", () => {\n        const result = validateJson('\"say \\\\\"hello\\\\\"\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates escaped backslash\", () => {\n        const result = validateJson('\"path\\\\\\\\to\\\\\\\\file\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates escaped control characters\", () => {\n        const result = validateJson('\"line1\\\\nline2\\\\ttab\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates escaped forward slash\", () => {\n        const result = validateJson('\"a\\\\/b\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates unicode escapes\", () => {\n        const result = validateJson('\"\\\\u0041\\\\u0042\\\\u0043\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates all escape types\", () => {\n        const result = validateJson('\"\\\\b\\\\f\\\\n\\\\r\\\\t\"');\n        expect(result.valid).toBe(true);\n      });\n    });\n\n    describe(\"whitespace handling\", () => {\n      test(\"validates with leading whitespace\", () => {\n        const result = validateJson(\"  \\n\\t  42\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates with trailing whitespace\", () => {\n        const result = validateJson(\"42  \\n\\t  \");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates object with various whitespace\", () => {\n        const result = validateJson('{\\n  \"key\" :\\t\"value\"\\n}');\n        expect(result.valid).toBe(true);\n      });\n    });\n\n    describe(\"invalid JSON\", () => {\n      test(\"rejects empty input\", () => {\n        const result = validateJson(\"\");\n        expect(result.valid).toBe(false);\n        expect(result.error).toBeDefined();\n      });\n\n      test(\"rejects whitespace-only input\", () => {\n        const result = validateJson(\"   \\n\\t  \");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects trailing comma in object\", () => {\n        const result = validateJson('{\"a\": 1,}');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects trailing comma in array\", () => {\n        const result = validateJson(\"[1, 2,]\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects unclosed object\", () => {\n        const result = validateJson('{\"a\": 1');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects unclosed array\", () => {\n        const result = validateJson(\"[1, 2\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects unclosed string\", () => {\n        const result = validateJson('\"hello');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects invalid escape sequence\", () => {\n        const result = validateJson('\"\\\\x41\"');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects incomplete unicode escape\", () => {\n        const result = validateJson('\"\\\\u00\"');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects invalid unicode hex digit\", () => {\n        const result = validateJson('\"\\\\u00GG\"');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects leading zeros in numbers\", () => {\n        const result = validateJson(\"01\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects plus prefix on numbers\", () => {\n        const result = validateJson(\"+1\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects trailing decimal point\", () => {\n        const result = validateJson(\"1.\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects multiple values\", () => {\n        const result = validateJson(\"1 2\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects single comma\", () => {\n        const result = validateJson(\",\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects unquoted object key\", () => {\n        const result = validateJson(\"{key: 1}\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects missing colon in object\", () => {\n        const result = validateJson('{\"key\" \"value\"}');\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects incomplete true literal\", () => {\n        const result = validateJson(\"tru\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects incomplete false literal\", () => {\n        const result = validateJson(\"fals\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects incomplete null literal\", () => {\n        const result = validateJson(\"nul\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"provides error position\", () => {\n        const result = validateJson('{\"a\": }');\n        expect(result.valid).toBe(false);\n        expect(result.position).toBeDefined();\n        expect(typeof result.position).toBe(\"number\");\n      });\n    });\n\n    describe(\"edge cases\", () => {\n      test(\"validates deeply nested structure\", () => {\n        let json = \"\";\n        for (let i = 0; i < 100; i++) json += \"[\";\n        json += \"1\";\n        for (let i = 0; i < 100; i++) json += \"]\";\n        const result = validateJson(json);\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates large numbers\", () => {\n        const result = validateJson(\"9999999999999999999999999999\");\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates empty string value\", () => {\n        const result = validateJson('\"\"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"validates string with only spaces\", () => {\n        const result = validateJson('\"   \"');\n        expect(result.valid).toBe(true);\n      });\n\n      test(\"rejects bare identifier\", () => {\n        const result = validateJson(\"undefined\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects NaN\", () => {\n        const result = validateJson(\"NaN\");\n        expect(result.valid).toBe(false);\n      });\n\n      test(\"rejects Infinity\", () => {\n        const result = validateJson(\"Infinity\");\n        expect(result.valid).toBe(false);\n      });\n    });\n  });\n\n  describe(\"validateJsonFast\", () => {\n    test(\"returns true for valid JSON object\", () => {\n      expect(validateJsonFast('{\"key\": \"value\"}')).toBe(true);\n    });\n\n    test(\"returns true for valid JSON array\", () => {\n      expect(validateJsonFast(\"[1, 2, 3]\")).toBe(true);\n    });\n\n    test(\"returns true for valid string\", () => {\n      expect(validateJsonFast('\"hello\"')).toBe(true);\n    });\n\n    test(\"returns true for valid number\", () => {\n      expect(validateJsonFast(\"42\")).toBe(true);\n    });\n\n    test(\"returns true for true\", () => {\n      expect(validateJsonFast(\"true\")).toBe(true);\n    });\n\n    test(\"returns true for false\", () => {\n      expect(validateJsonFast(\"false\")).toBe(true);\n    });\n\n    test(\"returns true for null\", () => {\n      expect(validateJsonFast(\"null\")).toBe(true);\n    });\n\n    test(\"returns false for empty input\", () => {\n      expect(validateJsonFast(\"\")).toBe(false);\n    });\n\n    test(\"returns false for invalid JSON\", () => {\n      expect(validateJsonFast(\"{invalid}\")).toBe(false);\n    });\n\n    test(\"returns false for trailing comma\", () => {\n      expect(validateJsonFast(\"[1,]\")).toBe(false);\n    });\n\n    test(\"returns false for unclosed brace\", () => {\n      expect(validateJsonFast('{\"a\": 1')).toBe(false);\n    });\n\n    test(\"returns true for complex nested JSON\", () => {\n      const json = '{\"users\": [{\"name\": \"Alice\", \"scores\": [100, 95.5, 1e2]}], \"valid\": true}';\n      expect(validateJsonFast(json)).toBe(true);\n    });\n\n    test(\"returns true for unicode escapes\", () => {\n      expect(validateJsonFast('\"\\\\u0041\"')).toBe(true);\n    });\n\n    test(\"returns false for invalid unicode escape\", () => {\n      expect(validateJsonFast('\"\\\\u00GG\"')).toBe(false);\n    });\n\n    test(\"returns false for multiple values\", () => {\n      expect(validateJsonFast(\"1 2\")).toBe(false);\n    });\n\n    test(\"returns false for leading zeros\", () => {\n      expect(validateJsonFast(\"01\")).toBe(false);\n    });\n  });\n});\n"
