        "content": "/**\n * Ultra-performant JSON validation module.\n * Uses single-pass character scanning with a manual state machine.\n * Zero intermediate allocations, no regex, no JSON.parse.\n */\n\nexport interface ValidationResult {\n  valid: boolean;\n  error?: string;\n  position?: number;\n}\n\nconst enum CharCode {\n  Tab = 0x09,\n  NewLine = 0x0a,\n  CarriageReturn = 0x0d,\n  Space = 0x20,\n  Quote = 0x22,\n  Comma = 0x2c,\n  Minus = 0x2d,\n  Dot = 0x2e,\n  Zero = 0x30,\n  Nine = 0x39,\n  Colon = 0x3a,\n  UpperA = 0x41,\n  UpperE = 0x45,\n  UpperF = 0x46,\n  OpenBracket = 0x5b,\n  Backslash = 0x5c,\n  CloseBracket = 0x5d,\n  LowerA = 0x61,\n  LowerB = 0x62,\n  LowerE = 0x65,\n  LowerF = 0x66,\n  LowerL = 0x6c,\n  LowerN = 0x6e,\n  LowerR = 0x72,\n  LowerS = 0x73,\n  LowerT = 0x74,\n  LowerU = 0x75,\n  OpenBrace = 0x7b,\n  CloseBrace = 0x7d,\n  Plus = 0x2b,\n}\n\nconst STACK_SIZE = 256;\n\nfunction isWhitespace(ch: number): boolean {\n  return ch === CharCode.Space || ch === CharCode.Tab || ch === CharCode.NewLine || ch === CharCode.CarriageReturn;\n}\n\nfunction isDigit(ch: number): boolean {\n  return ch >= CharCode.Zero && ch <= CharCode.Nine;\n}\n\nfunction isHexDigit(ch: number): boolean {\n  return (\n    (ch >= CharCode.Zero && ch <= CharCode.Nine) ||\n    (ch >= CharCode.LowerA && ch <= CharCode.LowerF) ||\n    (ch >= CharCode.UpperA && ch <= CharCode.UpperF)\n  );\n}\n\n/**\n * Validate JSON string with detailed error reporting.\n * Single-pass O(n) scanner with pre-allocated stack.\n */\nexport function validateJson(input: string): ValidationResult {\n  const len = input.length;\n\n  if (len === 0) {\n    return { valid: false, error: \"Empty input\", position: 0 };\n  }\n\n  // Pre-allocated container stack: 0 = object, 1 = array\n  const stack = new Uint8Array(STACK_SIZE);\n  let stackTop = -1;\n  let pos = 0;\n\n  // Skip leading whitespace\n  pos = skipWhitespace(input, pos, len);\n\n  if (pos >= len) {\n    return { valid: false, error: \"Empty input after whitespace\", position: pos };\n  }\n\n  // Parse the root value\n  const result = parseValue(input, pos, len, stack, { top: stackTop });\n  if (result.error) {\n    return { valid: false, error: result.error, position: result.pos };\n  }\n\n  // Skip trailing whitespace\n  pos = skipWhitespace(input, result.pos, len);\n\n  if (pos < len) {\n    return { valid: false, error: `Unexpected character '${input[pos]}' after JSON value`, position: pos };\n  }\n\n  return { valid: true };\n}\n\n/**\n * Fast boolean-only JSON validation.\n * Skips error message construction for maximum speed.\n */\nexport function validateJsonFast(input: string): boolean {\n  const len = input.length;\n  if (len === 0) return false;\n\n  const stack = new Uint8Array(STACK_SIZE);\n  let pos = skipWhitespace(input, 0, len);\n\n  if (pos >= len) return false;\n\n  const result = parseValueFast(input, pos, len, stack, { top: -1 });\n  if (!result.ok) return false;\n\n  pos = skipWhitespace(input, result.pos, len);\n  return pos >= len;\n}\n\nfunction skipWhitespace(input: string, pos: number, len: number): number {\n  while (pos < len && isWhitespace(input.charCodeAt(pos))) {\n    pos++;\n  }\n  return pos;\n}\n\ninterface StackRef {\n  top: number;\n}\n\ninterface ParseResult {\n  pos: number;\n  error?: string;\n}\n\ninterface ParseResultFast {\n  pos: number;\n  ok: boolean;\n}\n\nfunction parseValue(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResult {\n  if (pos >= len) return { pos, error: \"Unexpected end of input\" };\n\n  const ch = input.charCodeAt(pos);\n\n  switch (ch) {\n    case CharCode.OpenBrace:\n      return parseObject(input, pos, len, stack, ref);\n    case CharCode.OpenBracket:\n      return parseArray(input, pos, len, stack, ref);\n    case CharCode.Quote:\n      return parseString(input, pos, len);\n    case CharCode.LowerT:\n      return parseLiteral(input, pos, len, \"true\");\n    case CharCode.LowerF:\n      return parseLiteral(input, pos, len, \"false\");\n    case CharCode.LowerN:\n      return parseLiteral(input, pos, len, \"null\");\n    default:\n      if (ch === CharCode.Minus || isDigit(ch)) {\n        return parseNumber(input, pos, len);\n      }\n      return { pos, error: `Unexpected character '${input[pos]}'` };\n  }\n}\n\nfunction parseObject(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResult {\n  ref.top++;\n  if (ref.top >= STACK_SIZE) return { pos, error: \"Nesting too deep\" };\n  stack[ref.top] = 0;\n\n  pos++; // skip '{'\n  pos = skipWhitespace(input, pos, len);\n\n  if (pos >= len) return { pos, error: \"Unexpected end of input in object\" };\n\n  if (input.charCodeAt(pos) === CharCode.CloseBrace) {\n    ref.top--;\n    return { pos: pos + 1 };\n  }\n\n  while (true) {\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len) return { pos, error: \"Unexpected end of input in object\" };\n\n    // Key must be a string\n    if (input.charCodeAt(pos) !== CharCode.Quote) {\n      return { pos, error: \"Expected string key in object\" };\n    }\n    const keyResult = parseString(input, pos, len);\n    if (keyResult.error) return keyResult;\n    pos = keyResult.pos;\n\n    // Expect colon\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len || input.charCodeAt(pos) !== CharCode.Colon) {\n      return { pos, error: \"Expected ':' after object key\" };\n    }\n    pos++;\n\n    // Parse value\n    pos = skipWhitespace(input, pos, len);\n    const valResult = parseValue(input, pos, len, stack, ref);\n    if (valResult.error) return valResult;\n    pos = valResult.pos;\n\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len) return { pos, error: \"Unexpected end of input in object\" };\n\n    const next = input.charCodeAt(pos);\n    if (next === CharCode.CloseBrace) {\n      ref.top--;\n      return { pos: pos + 1 };\n    }\n    if (next === CharCode.Comma) {\n      pos++;\n      continue;\n    }\n    return { pos, error: `Expected ',' or '}' in object, got '${input[pos]}'` };\n  }\n}\n\nfunction parseArray(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResult {\n  ref.top++;\n  if (ref.top >= STACK_SIZE) return { pos, error: \"Nesting too deep\" };\n  stack[ref.top] = 1;\n\n  pos++; // skip '['\n  pos = skipWhitespace(input, pos, len);\n\n  if (pos >= len) return { pos, error: \"Unexpected end of input in array\" };\n\n  if (input.charCodeAt(pos) === CharCode.CloseBracket) {\n    ref.top--;\n    return { pos: pos + 1 };\n  }\n\n  while (true) {\n    pos = skipWhitespace(input, pos, len);\n    const valResult = parseValue(input, pos, len, stack, ref);\n    if (valResult.error) return valResult;\n    pos = valResult.pos;\n\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len) return { pos, error: \"Unexpected end of input in array\" };\n\n    const next = input.charCodeAt(pos);\n    if (next === CharCode.CloseBracket) {\n      ref.top--;\n      return { pos: pos + 1 };\n    }\n    if (next === CharCode.Comma) {\n      pos++;\n      continue;\n    }\n    return { pos, error: `Expected ',' or ']' in array, got '${input[pos]}'` };\n  }\n}\n\nfunction parseString(input: string, pos: number, len: number): ParseResult {\n  pos++; // skip opening quote\n\n  while (pos < len) {\n    const ch = input.charCodeAt(pos);\n\n    if (ch === CharCode.Quote) {\n      return { pos: pos + 1 };\n    }\n\n    if (ch === CharCode.Backslash) {\n      pos++;\n      if (pos >= len) return { pos, error: \"Unexpected end of input in string escape\" };\n      const esc = input.charCodeAt(pos);\n      switch (esc) {\n        case CharCode.Quote:\n        case CharCode.Backslash:\n        case 0x2f: // '/'\n        case CharCode.LowerB:\n        case CharCode.LowerF:\n        case CharCode.LowerN:\n        case CharCode.LowerR:\n        case CharCode.LowerT:\n          pos++;\n          break;\n        case CharCode.LowerU:\n          pos++;\n          for (let i = 0; i < 4; i++) {\n            if (pos >= len) return { pos, error: \"Unexpected end of input in unicode escape\" };\n            if (!isHexDigit(input.charCodeAt(pos))) {\n              return { pos, error: `Invalid hex digit in unicode escape: '${input[pos]}'` };\n            }\n            pos++;\n          }\n          break;\n        default:\n          return { pos: pos - 1, error: `Invalid escape sequence '\\\\${input[pos]}'` };\n      }\n      continue;\n    }\n\n    // Control characters (0x00-0x1f) are invalid in JSON strings\n    if (ch < 0x20) {\n      return { pos, error: `Invalid control character in string at position ${pos}` };\n    }\n\n    pos++;\n  }\n\n  return { pos, error: \"Unterminated string\" };\n}\n\nfunction parseLiteral(input: string, pos: number, len: number, literal: string): ParseResult {\n  const litLen = literal.length;\n  if (pos + litLen > len) {\n    return { pos, error: `Unexpected end of input, expected '${literal}'` };\n  }\n  for (let i = 0; i < litLen; i++) {\n    if (input.charCodeAt(pos + i) !== literal.charCodeAt(i)) {\n      return { pos: pos + i, error: `Expected '${literal}', got '${input.substring(pos, pos + litLen)}'` };\n    }\n  }\n  return { pos: pos + litLen };\n}\n\nfunction parseNumber(input: string, pos: number, len: number): ParseResult {\n  const start = pos;\n\n  // Optional minus\n  if (pos < len && input.charCodeAt(pos) === CharCode.Minus) {\n    pos++;\n  }\n\n  if (pos >= len) return { pos, error: \"Unexpected end of input in number\" };\n\n  // Integer part\n  if (input.charCodeAt(pos) === CharCode.Zero) {\n    pos++;\n    // After leading zero, must not be followed by another digit\n    if (pos < len && isDigit(input.charCodeAt(pos))) {\n      return { pos, error: \"Leading zeros are not allowed\" };\n    }\n  } else if (isDigit(input.charCodeAt(pos))) {\n    while (pos < len && isDigit(input.charCodeAt(pos))) {\n      pos++;\n    }\n  } else {\n    return { pos, error: \"Expected digit in number\" };\n  }\n\n  // Fractional part\n  if (pos < len && input.charCodeAt(pos) === CharCode.Dot) {\n    pos++;\n    if (pos >= len || !isDigit(input.charCodeAt(pos))) {\n      return { pos, error: \"Expected digit after decimal point\" };\n    }\n    while (pos < len && isDigit(input.charCodeAt(pos))) {\n      pos++;\n    }\n  }\n\n  // Exponent part\n  if (pos < len && (input.charCodeAt(pos) === CharCode.LowerE || input.charCodeAt(pos) === CharCode.UpperE)) {\n    pos++;\n    if (pos < len && (input.charCodeAt(pos) === CharCode.Plus || input.charCodeAt(pos) === CharCode.Minus)) {\n      pos++;\n    }\n    if (pos >= len || !isDigit(input.charCodeAt(pos))) {\n      return { pos, error: \"Expected digit in exponent\" };\n    }\n    while (pos < len && isDigit(input.charCodeAt(pos))) {\n      pos++;\n    }\n  }\n\n  if (pos === start) {\n    return { pos, error: \"Invalid number\" };\n  }\n\n  return { pos };\n}\n\n// --- Fast variants (boolean-only, no error messages) ---\n\nfunction parseValueFast(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResultFast {\n  if (pos >= len) return { pos, ok: false };\n\n  const ch = input.charCodeAt(pos);\n\n  switch (ch) {\n    case CharCode.OpenBrace:\n      return parseObjectFast(input, pos, len, stack, ref);\n    case CharCode.OpenBracket:\n      return parseArrayFast(input, pos, len, stack, ref);\n    case CharCode.Quote:\n      return parseStringFast(input, pos, len);\n    case CharCode.LowerT:\n      return parseLiteralFast(input, pos, len, \"true\");\n    case CharCode.LowerF:\n      return parseLiteralFast(input, pos, len, \"false\");\n    case CharCode.LowerN:\n      return parseLiteralFast(input, pos, len, \"null\");\n    default:\n      if (ch === CharCode.Minus || isDigit(ch)) {\n        return parseNumberFast(input, pos, len);\n      }\n      return { pos, ok: false };\n  }\n}\n\nfunction parseObjectFast(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResultFast {\n  ref.top++;\n  if (ref.top >= STACK_SIZE) return { pos, ok: false };\n  stack[ref.top] = 0;\n\n  pos++;\n  pos = skipWhitespace(input, pos, len);\n\n  if (pos >= len) return { pos, ok: false };\n  if (input.charCodeAt(pos) === CharCode.CloseBrace) {\n    ref.top--;\n    return { pos: pos + 1, ok: true };\n  }\n\n  while (true) {\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len || input.charCodeAt(pos) !== CharCode.Quote) return { pos, ok: false };\n    const kr = parseStringFast(input, pos, len);\n    if (!kr.ok) return kr;\n    pos = kr.pos;\n\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len || input.charCodeAt(pos) !== CharCode.Colon) return { pos, ok: false };\n    pos++;\n\n    pos = skipWhitespace(input, pos, len);\n    const vr = parseValueFast(input, pos, len, stack, ref);\n    if (!vr.ok) return vr;\n    pos = vr.pos;\n\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len) return { pos, ok: false };\n\n    const next = input.charCodeAt(pos);\n    if (next === CharCode.CloseBrace) {\n      ref.top--;\n      return { pos: pos + 1, ok: true };\n    }\n    if (next === CharCode.Comma) {\n      pos++;\n      continue;\n    }\n    return { pos, ok: false };\n  }\n}\n\nfunction parseArrayFast(input: string, pos: number, len: number, stack: Uint8Array, ref: StackRef): ParseResultFast {\n  ref.top++;\n  if (ref.top >= STACK_SIZE) return { pos, ok: false };\n  stack[ref.top] = 1;\n\n  pos++;\n  pos = skipWhitespace(input, pos, len);\n\n  if (pos >= len) return { pos, ok: false };\n  if (input.charCodeAt(pos) === CharCode.CloseBracket) {\n    ref.top--;\n    return { pos: pos + 1, ok: true };\n  }\n\n  while (true) {\n    pos = skipWhitespace(input, pos, len);\n    const vr = parseValueFast(input, pos, len, stack, ref);\n    if (!vr.ok) return vr;\n    pos = vr.pos;\n\n    pos = skipWhitespace(input, pos, len);\n    if (pos >= len) return { pos, ok: false };\n\n    const next = input.charCodeAt(pos);\n    if (next === CharCode.CloseBracket) {\n      ref.top--;\n      return { pos: pos + 1, ok: true };\n    }\n    if (next === CharCode.Comma) {\n      pos++;\n      continue;\n    }\n    return { pos, ok: false };\n  }\n}\n\nfunction parseStringFast(input: string, pos: number, len: number): ParseResultFast {\n  pos++;\n  while (pos < len) {\n    const ch = input.charCodeAt(pos);\n    if (ch === CharCode.Quote) return { pos: pos + 1, ok: true };\n    if (ch === CharCode.Backslash) {\n      pos++;\n      if (pos >= len) return { pos, ok: false };\n      const esc = input.charCodeAt(pos);\n      if (esc === CharCode.LowerU) {\n        pos++;\n        for (let i = 0; i < 4; i++) {\n          if (pos >= len || !isHexDigit(input.charCodeAt(pos))) return { pos, ok: false };\n          pos++;\n        }\n        continue;\n      }\n      if (\n        esc === CharCode.Quote || esc === CharCode.Backslash || esc === 0x2f ||\n        esc === CharCode.LowerB || esc === CharCode.LowerF || esc === CharCode.LowerN ||\n        esc === CharCode.LowerR || esc === CharCode.LowerT\n      ) {\n        pos++;\n        continue;\n      }\n      return { pos, ok: false };\n    }\n    if (ch < 0x20) return { pos, ok: false };\n    pos++;\n  }\n  return { pos, ok: false };\n}\n\nfunction parseLiteralFast(input: string, pos: number, len: number, literal: string): ParseResultFast {\n  const litLen = literal.length;\n  if (pos + litLen > len) return { pos, ok: false };\n  for (let i = 0; i < litLen; i++) {\n    if (input.charCodeAt(pos + i) !== literal.charCodeAt(i)) return { pos, ok: false };\n  }\n  return { pos: pos + litLen, ok: true };\n}\n\nfunction parseNumberFast(input: string, pos: number, len: number): ParseResultFast {\n  if (pos < len && input.charCodeAt(pos) === CharCode.Minus) pos++;\n  if (pos >= len) return { pos, ok: false };\n\n  if (input.charCodeAt(pos) === CharCode.Zero) {\n    pos++;\n    if (pos < len && isDigit(input.charCodeAt(pos))) return { pos, ok: false };\n  } else if (isDigit(input.charCodeAt(pos))) {\n    while (pos < len && isDigit(input.charCodeAt(pos))) pos++;\n  } else {\n    return { pos, ok: false };\n  }\n\n  if (pos < len && input.charCodeAt(pos) === CharCode.Dot) {\n    pos++;\n    if (pos >= len || !isDigit(input.charCodeAt(pos))) return { pos, ok: false };\n    while (pos < len && isDigit(input.charCodeAt(pos))) pos++;\n  }\n\n  if (pos < len && (input.charCodeAt(pos) === CharCode.LowerE || input.charCodeAt(pos) === CharCode.UpperE)) {\n    pos++;\n    if (pos < len && (input.charCodeAt(pos) === CharCode.Plus || input.charCodeAt(pos) === CharCode.Minus)) pos++;\n    if (pos >= len || !isDigit(input.charCodeAt(pos))) return { pos, ok: false };\n    while (pos < len && isDigit(input.charCodeAt(pos))) pos++;\n  }\n\n  return { pos, ok: true };\n}\n"
